   $('#cab-tools').onchange=()=>{if(refreshing)return;try{draft=read();refresh();}catch(e){error(e.message);}};$('#cab-tools').onclick=e=>{const button=e.target.closest('[data-cab-op]');if(button)structure(button.dataset.cabOp);};
   $('#cab-bay-picker').onpointerdown=e=>{const summary=e.target.closest('.cab-object-finder>summary');if(summary)finderOpen=!summary.parentElement.open;};$('#cab-bay-picker').onchange=e=>{if(e.target.hasAttribute('data-cab-find-group')){finderOpen=true;inspect({kind:'bay',column:Number(e.target.value)});}else if(e.target.id==='cab-object-target'){finderOpen=false;inspect(JSON.parse(e.target.value));}};$('#cab-bay-picker').oninput=cabinetFilterParts;$('#cab-bay-picker').onkeydown=cabinetFinderKey;$('#cab-bay-picker').onclick=e=>{const pick=e.target.closest('[data-cab-pick]');if(pick){finderOpen=false;inspect(JSON.parse(pick.dataset.cabPick));return;}const b=e.target.closest('[data-cab-target]');if(b)inspect(b.dataset.cabTarget==='body'?null:{kind:'bay',column:selected.column});};
